sub stoi {
  my ($s)=@_;
  my $i=0; my $n=length $s;
  $i++ while $i<$n && substr($s,$i,1)=~/[ \t\n\x0b\f\r]/;
  my $sign=1;
  if($i<$n && substr($s,$i,1)=~/[+-]/){ $sign=-1 if substr($s,$i,1) eq '-'; $i++; }
  my $d='';
  while($i<$n && substr($s,$i,1)=~/[0-9]/){ $d.=substr($s,$i,1); $i++; }
  return undef if $d eq '';
  my $v=$sign*($d+0);
  return undef if $v < -2147483648 || $v > 2147483647;
  return $v;
}
sub parse {
  my ($s)=@_;
  my $i=index($s,'#'); $s=substr($s,0,$i) if $i>=0;
  my $j=index($s,'?'); $s=substr($s,0,$j) if $j>=0;
  my ($scheme,$host,$port,$path)=('','',-1,'');
  my $k=index($s,'://');
  if($k>=0){
    $scheme=substr($s,0,$k); my $rest=substr($s,$k+3);
    my $sl=index($rest,'/'); my $auth;
    if($sl>=0){ $auth=substr($rest,0,$sl); $path=substr($rest,$sl); } else { $auth=$rest; $path=''; }
    my $hp=$auth; my $at=index($auth,'@');
    $hp=substr($auth,$at+1) if $at>=0;
    my $c=index($hp,':');
    if($c>=0){ $host=substr($hp,0,$c); my $v=stoi(substr($hp,$c+1)); $port = defined($v)?$v:-1; }
    else { $host=$hp; }
  } else { $path=$s; }
  return ($scheme,$host,$port,$path);
}
sub scheme_valid { my($x)=@_; return 0 if $x eq ''; return 0 unless substr($x,0,1)=~/[A-Za-z]/; return 0 unless substr($x,1)=~/^[A-Za-z0-9+\-.]*$/; return 1 }
sub host_valid { my($x)=@_; return 0 if $x eq ''; return $x=~/^[A-Za-z0-9\-.\[\]]+$/ ? 1:0 }
sub predict {
  my ($s)=@_;
  my ($sc,$h,$po,$pa)=parse($s);
  my @segs=grep { length } split(/\//,$pa,-1);
  my @o=( (($h ne '' || $pa ne '')?1:0), scheme_valid($sc), host_valid($h), (($po>=0 && $po<=65535)?1:0), scalar(@segs), @segs);
  return join("\n",@o)."\n";
}
